import{_ as a,o,c as t,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Historical Runbook — AI Service EC2 Rebalance (2026-11-03)","description":"","frontmatter":{},"headers":[],"relativePath":"operations/history/2026-11-03-rebalance-ai.md","filePath":"operations/history/2026-11-03-rebalance-ai.md"}'),r={name:"operations/history/2026-11-03-rebalance-ai.md"};function n(s,e,c,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="historical-runbook-—-ai-service-ec2-rebalance-2026-11-03" tabindex="-1">Historical Runbook — AI Service EC2 Rebalance (2026-11-03) <a class="header-anchor" href="#historical-runbook-—-ai-service-ec2-rebalance-2026-11-03" aria-label="Permalink to &quot;Historical Runbook — AI Service EC2 Rebalance (2026-11-03)&quot;">​</a></h1><p>&gt; <a href="./../../">&lt;&lt; Knowledge Base Home</a> · <a href="./../README.html">Operations</a> · <a href="./../deployment-acct134.html">Current Prod Deployment</a></p><p>&gt; <strong>Account 134875421878 (2026-11-19):</strong> AI runs on <code>brandhub-ai</code> <code>i-0f7857edf71b6bb3f</code> (<code>172.31.20.60</code>); see <a href="./../deployment-acct134.html">deployment-acct134.md</a>. &gt; &gt; <strong>Superseded 2026-11-16:</strong> AI now runs alone on <code>brandhub-ai</code> (<code>i-0c91c9509effc20e4</code>, <code>172.31.20.60</code>, c7i-flex.large 4 GiB) from <code>ai.compose.json</code> (3 GiB limit, Redis/RabbitMQ/Chroma via <code>extra_hosts</code> to <code>172.31.24.149</code>). Business and crawl use <code>AI_SERVICE_URL=http://172.31.20.60:8082</code>. The old <code>brandhub-ai-service</code> container on the service EC2 is stopped (<code>restart=no</code>) and its volumes kept for rollback; backups are in <code>rebalance-ai-20261116T*</code> on the service and crawl hosts.</p><p>Status: applied to production on 2026-11-03 with user authorization. The procedure below is retained as a migration/rollback reference.</p><h2 id="deployment-result" tabindex="-1">Deployment result <a class="header-anchor" href="#deployment-result" aria-label="Permalink to &quot;Deployment result&quot;">​</a></h2><ul><li>Existing EC2 instances retained; gateway EBS expanded from 10 to 20 GiB and XFS grown online. Service EBS remains 20 GiB.</li><li>Terraform applied three private ingress rules and two in-place resource updates. Final <code>terraform plan -detailed-exitcode</code> returned 0: <strong>No changes</strong>.</li><li>AI runs only on gateway with 5 GiB RAM and 1.5 CPUs. Source AI container is stopped and retained. Both live manifests preserve the original running image tags; checked-in Compose image tags now reflect this deployment snapshot too.</li><li>Source and destination crawler data matched by file count and aggregate content hashes (302 files). Model cache (about 1.5 GiB) transferred to its persistent named volume over compressed SSH. Private backups are under <code>/home/ec2-user/brandhub/ecr/rebalance-20261103/</code> on each host; never publish their env files.</li><li>Verified authenticated Redis/RabbitMQ connections, private Chroma heartbeat, Neo4j/tracking/worker/scheduler checks, appuser data/cache permissions and Business-container access to the new AI private endpoint.</li><li>Verified public HTTPS health 200/UP, login validation 400 through Business, and protected unauthenticated request 401.</li><li>Real crawler browser launch/render/close smoke passed on a self-contained data URL. New AI cgroup OOM counters remained zero and restart count was zero. A first synthetic <code>set_content</code> smoke timed out waiting for a load event; the self-contained navigation test passed without application changes.</li><li>Idle RAM available after migration was about 5.7 GiB on gateway and 5.8 GiB on service. Gateway disk usage was about 9/20 GiB. These are idle snapshots, not peak-crawl measurements.</li><li>AI/gateway deploy workflows updated on GitHub <code>develop</code> and read back successfully. Their <code>main</code> branches had no corresponding deployment workflow file, so none was created there. AI commit: <code>b7a4f9e7c03ac89e1c21a051719c05285b5cf6b2</code>; gateway commit: <code>ddbc03f912d52aa9413e9634ac006160400964e8</code>.</li><li>All four application deploy workflows re-enabled. Temporary administrator-IP-only SSH rules removed. No database volumes or rollback data deleted.</li><li>Full crawl validation remains pending session re-upload. Management reports Facebook/Threads <code>SESSION_MISSING</code>, TikTok <code>TIKTOK_NOT_CONFIGURED</code>, and <code>secretStorageReady=false</code>. Proxy and runtime dependencies report OK. Do not claim the original full-crawl OOM is resolved from these smoke checks alone.</li></ul><h2 id="preconditions-and-approval-boundary" tabindex="-1">Preconditions and approval boundary <a class="header-anchor" href="#preconditions-and-approval-boundary" aria-label="Permalink to &quot;Preconditions and approval boundary&quot;">​</a></h2><ul><li>Source: <code>i-07283e8467a059e5a</code>, private IP <code>172.31.24.149</code>.</li><li>Destination: <code>i-0761e3bd96ca5d4de</code>, private IP <code>172.31.27.199</code>.</li><li>Working directory on both: <code>/home/ec2-user/brandhub/ecr</code>.</li><li>Confirm a short maintenance window and that the operator can re-upload Facebook/Threads sessions. <code>CrawlerSecrets</code> holds these sessions only in API process RAM; restarting or moving the process loses them. A volume backup does not preserve them.</li><li>Approve gateway EBS growth from 10 to 20 GiB. This incurs additional EBS storage cost and cannot be rolled back by shrinking the volume. No EC2 type change or additional EC2 is needed.</li><li>Pause application CI while copying/changing manifests. Merge/release the AI target change and both host-lock changes together with cutover, before resuming CI. Unchanged AI CI targets the old host.</li><li>AWS SSM is online on both machines. Direct administrator SSH currently times out because its configured admin CIDR differs from the current network. Use an authenticated SSM SSH tunnel or a temporary administrator-IP-only SSH rule; verify host keys through SSM, and remove temporary access after transfer. Never open SSH globally.</li></ul><h2 id="_1-prepare-and-inspect-the-infrastructure-plan" tabindex="-1">1. Prepare and inspect the infrastructure plan <a class="header-anchor" href="#_1-prepare-and-inspect-the-infrastructure-plan" aria-label="Permalink to &quot;1. Prepare and inspect the infrastructure plan&quot;">​</a></h2><p>From <code>prod/terraform/3. backend-prod</code>, use the existing production inputs, with <code>instances.api_gateway.root_volume_size = 20</code> and <code>instances.core_services.root_volume_size = 20</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>terraform fmt -check</span></span>
<span class="line"><span>terraform validate</span></span>
<span class="line"><span>terraform plan -out=&lt;private-local-plan-path&gt;</span></span></code></pre></div><p>Expected: three SG ingress resources added; gateway root volume 10 -&gt; 20 GiB. Existing configuration also reconciles EC2/volume Name and Service tags and renamed outputs. No AMI/instance type/IP changes, deletions or replacements are expected. Service root stays 20 GiB. If the plan proposes shrinking a disk, stop. Recheck the saved plan immediately before applying it; do not reuse a stale plan after production changes.</p><p>After approved apply, inspect <code>lsblk -f</code> and <code>df -h /</code> on gateway. If the filesystem has not expanded, identify its actual partition/filesystem first, then use the matching <code>growpart</code> and <code>xfs_growfs</code>/<code>resize2fs</code> commands. Do not assume device names or format a filesystem.</p><h2 id="_2-stage-without-starting-another-scheduler" tabindex="-1">2. Stage without starting another scheduler <a class="header-anchor" href="#_2-stage-without-starting-another-scheduler" aria-label="Permalink to &quot;2. Stage without starting another scheduler&quot;">​</a></h2><ol><li>Make private, timestamped backups of both live Compose files and affected env files on their own hosts. Keep the original source AI container and <code>brandhub-ai-data</code> volume for rollback.</li><li>Record the actual running image tags from Docker inspect. At inspection AI used <code>sha-a42b445-36</code>, Business <code>sha-d9a0bbe-113</code>, Publisher <code>sha-819bf14-32</code>. Re-read these values at deployment time. The repo&#39;s <code>deploy-20261029</code> images are historical baselines: <strong>do not copy repo manifests wholesale over production</strong>.</li><li>Patch copies of the live manifests with only the placement/limits/network/volume changes in the checked-in Compose diff. Preserve all current image tags and unrelated settings. Destination AI definition comes from the live source AI, with its old <code>depends_on</code> removed, plus the checked-in backend AI resource limits, private binding, environment overrides, host aliases and model-cache mount.</li><li>Transfer <code>env/ai-service.env</code> over encrypted transport directly into destination <code>env/</code> (0700 directory, 0600 file). Do not print its contents or send them as SSM command text. Inspect configured file paths without printing their contents; copy any referenced secret-key/session files outside <code>/app/data</code> to equivalent private paths and preserve their permissions/mounts. RAM-only sessions still need re-upload.</li><li>Check <code>REDIS_URL</code> hostname only, without logging credentials. Existing <code>redis</code> host is resolved by <code>extra_hosts</code>; if it uses another host, make an explicit private-endpoint adjustment in the runtime file. Set <code>REDIS_HOST</code>, <code>RABBITMQ_HOST</code>, <code>CHROMADB_HOST</code> via Compose as checked in.</li><li>Authenticate ECR with the EC2 role and pull the <strong>current source AI tag</strong> on gateway. Check free disk before and after. Do not start AI yet.</li><li>Create destination named volumes <code>brandhub-ai-data</code> and <code>brandhub-ai-model-cache</code>. Inspect them first; stop if they already contain unrelated data. Copy the source <code>/home/appuser/.cache</code> tree from the AI container into the cache volume using Docker copy/tar over encrypted transport. Preserve ownership, symlinks and mode bits; the inspected cache was about 1.5 GiB. It currently resides in the container writable layer.</li><li>Validate both staged manifests on their intended hosts with <code>docker compose -f &lt;file&gt; config -q</code>. Do not print resolved Compose config because it can contain credentials.</li></ol><h2 id="_3-cut-over" tabindex="-1">3. Cut over <a class="header-anchor" href="#_3-cut-over" aria-label="Permalink to &quot;3. Cut over&quot;">​</a></h2><ol><li>Wait for the active crawl to finish; inspect crawler state using the existing management API. Stop if a run is still active. Keep CI paused.</li><li>Stop source <code>ai-service</code> gracefully. Confirm all source scheduler/browser/consumer processes have exited before starting destination AI.</li><li>Transfer the now-consistent <code>brandhub-ai-data</code> volume to destination over encrypted transport, preserving ownership and mode bits. Compare file counts and hashes without printing file contents. Do not transfer a live, changing state directory.</li><li>Install patched service manifest. Recreate <strong>only</strong> <code>rabbitmq</code> and <code>chromadb</code> to publish 5672/8000 on the source private IP. Their named data volumes remain unchanged. Wait for health; broker reconnections may briefly affect Business/Publisher. Redis already has a private 6379 binding and need not be recreated.</li><li>Install patched backend manifest and start only <code>ai-service</code>, using <code>docker compose -f backend.compose.json up -d --no-deps --no-build --wait --wait-timeout 240 ai-service</code>. Confirm the original source AI remains stopped.</li><li>Verify from destination AI that Redis authenticates, RabbitMQ connects and Chroma responds. Probe <code>/health</code> and <code>/api/v2/heartbeat</code> on Chroma through its private binding as applicable. Verify the named cache volume is readable/writable by appuser.</li><li>Install the Business <code>AI_SERVICE_URL=http://172.31.27.199:8082</code> override and recreate only Business. Verify Business can reach AI and public HTTPS requests still reach Business through gateway. Expect a short Business interruption with one replica.</li><li>Re-upload Facebook/Threads sessions through the existing authenticated UI. Run one bounded crawl with the intended worker processing enabled. Record memory peak and OOM counters on the new AI cgroup, container restarts, RAM available on both hosts, gateway health and response latency. A passing <code>/health</code> alone is insufficient.</li><li>Resume CI only after workflow changes point AI at destination and both workflows use the shared host lock. Confirm there is exactly one AI scheduler/consumer deployment. Keep rollback assets until the crawl is verified. Remove temporary transfer access, if any.</li></ol><h2 id="_4-roll-back-on-connectivity-health-or-resource-failure" tabindex="-1">4. Roll back on connectivity, health or resource failure <a class="header-anchor" href="#_4-roll-back-on-connectivity-health-or-resource-failure" aria-label="Permalink to &quot;4. Roll back on connectivity, health or resource failure&quot;">​</a></h2><ol><li>Stop destination AI first, to avoid two schedulers/consumers. Keep CI paused and prevent scheduled jobs during rollback.</li><li>If destination accepted writes or completed jobs, preserve its data and reconcile queue/state with source before restart; do not blindly replace current state with a stale source copy.</li><li>Restore the source live Compose/env backup, keeping its original image tag and AI memory limit. Restore Business&#39;s old <code>AI_SERVICE_URL</code>. Start source AI and recreate Business, then verify internal dependencies and public health. Sessions may need re-upload here too.</li><li>Restore backend manifest without AI. Keep destination data/cache volumes for recovery; do not run <code>down -v</code> or prune volumes.</li><li>Restore the AI CI target to source before resuming deployments if the migration is abandoned. Gateway EBS remains 20 GiB; it cannot be shrunk in place. Extra internal SG rules can be removed through a reviewed Terraform plan after no migrated traffic uses them.</li></ol><h2 id="verified-preparation" tabindex="-1">Verified preparation <a class="header-anchor" href="#verified-preparation" aria-label="Permalink to &quot;Verified preparation&quot;">​</a></h2><ul><li>Local Compose structure validation passes with <code>config --no-env-resolution --no-interpolate -q</code>; this does not validate production credentials or dependency reachability.</li><li>Terraform validation and format check pass. Reviewed plan: 3 additions, 2 in-place changes, 0 destroys; only gateway root capacity grows.</li><li>Cross-repository deployment race identified in review and addressed with the same host-level <code>flock</code> in AI/gateway workflows.</li><li>Production cutover and model-cache transfer completed; actual authenticated crawl verification remains pending session re-upload.</li></ul>`,21)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
